"use strict";document.addEventListener("DOMContentLoaded",function(){if(window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;var flows=document.querySelectorAll(".flow-anim");if(!("IntersectionObserver"in window)){flows.forEach(function(f){f.classList.add("play")});return;}var io=new IntersectionObserver(function(es){es.forEach(function(en){if(en.isIntersecting){en.target.classList.add("play");io.unobserve(en.target)}})},{threshold:.3});flows.forEach(function(f){io.observe(f)});});